{
  "id": "update-project-version",
  "label": "render update version script",
  "description": "Generate a version update script for this project.",
  "type": "agent",
  "appliesTo": {
    "kind": "project"
  },
  "prompt": "Update this project's version to {{version}}. First read the project's release and build documentation, then inspect its actual manifests and existing version scripts. Determine which files this project owns and what version format each expects; for example, a project may require MAJOR.MINOR.PATCH, but do not impose that format on another project. Create or update a project-specific script that validates its input, updates the explicitly identified files to the supplied value, and reports failures without leaving any single file partially written. Run that script with the supplied version. Add focused tests for the script and run only relevant checks. Report files changed and any failure."
}

import { describe, expect, it } from 'vitest'
import { createDefaultActionFiles } from './project_template'

describe('createDefaultActionFiles', () => {
    it('bundles a project version action that asks for input and delegates script generation', () => {
        const files = createDefaultActionFiles('design/actions')
        const file = files.find(({ path }) => path === 'design/actions/update-project-version.json')
        if (!file) throw new Error('Missing bundled version action')
        const definition = JSON.parse(file.content) as { prompt: string, userInput: { type: string } }

        expect(definition.userInput.type).toBe('version')
        expect(definition.prompt).toContain('{{version}}')
        expect(definition.prompt).toContain('project-specific script')
    })
    it('uses portable repository paths when combining a bundled action path with card-file', () => {
        const files = createDefaultActionFiles('design/actions')
        const implementFile = files.find(({ path }) => path === 'design/actions/implement.json')
        if (!implementFile) throw new Error('Missing bundled implement action')

        const definition = JSON.parse(implementFile.content) as { prompt: string }

        expect(definition.prompt).toContain('{{repository-folder}}/{{card-file}}')
        expect(definition.prompt).not.toContain('{{project-folder}}\\{{card-file}}')
    })
    it('uses portable paths in the bundled release-note action', () => {
        const files = createDefaultActionFiles('design/actions')
        const file = files.find(({ path }) => path === 'design/actions/write-release-note.json')
        if (!file) throw new Error('Missing bundled release-note action')
        const definition = JSON.parse(file.content) as { prompt: string }

        expect(definition.prompt).toContain('{{repository-folder}}/desktop/package.json')
        expect(definition.prompt).toContain('releases/{VERSION}/release')
    })

})

import type { MarkdownFile } from '../data/data_types'

const DEFAULT_ACTION_TEMPLATES = import.meta.glob<string>('./actions/*.json', {
    eager: true,
    import: 'default',
    query: '?raw',
})

/** Build default action files under a project's resolved actions folder. */
export function createDefaultActionFiles(actionsFolder: string): MarkdownFile[] {
    if (actionsFolder.length === 0) throw new Error('Missing default actions folder')

    return Object.entries(DEFAULT_ACTION_TEMPLATES)
        .sort(([leftPath], [rightPath]) => leftPath.localeCompare(rightPath))
        .map(([templatePath, content]) => {
            const fileName = templatePath.slice(templatePath.lastIndexOf('/') + 1)

            return { content, path: `${actionsFolder}/${fileName}` }
        })
}

